struct DrivenState {Spins m;unsigned long steps=0;double origin=0,Dtotal=0,Ptotal=0;std::array<double,2>D{},P{};std::array<Track,2>track;};
void driven_cp(const std::filesystem::path&p,const DrivenState&s,const UserConfig&u,const std::string&id){auto tmp=p;tmp+=".tmp";std::ofstream f(tmp,std::ios::binary);auto put=[&](const auto&v){f.write((const char*)&v,sizeof(v));};std::uint64_t magic=0x315043544f534946ULL,n=u.c.count,length=id.size();put(magic);put(n);put(length);f.write(id.data(),length);for(int q:u.c.n)put(q);put(s.steps);put(s.origin);for(double q:s.D)put(q);for(double q:s.P)put(q);put(s.Dtotal);put(s.Ptotal);for(auto&sub:s.m)for(V v:sub){put(v.x);put(v.y);put(v.z);}for(auto&t:s.track){for(double q:t.wrapped)put(q);for(double q:t.unwrapped)put(q);put(t.has);put(t.continuous);}f.flush();if(!f)throw std::runtime_error("driven checkpoint write");f.close();std::filesystem::rename(tmp,p);}
DrivenState restore_driven(const std::filesystem::path&p,const UserConfig&u,const std::string&id){std::ifstream f(p,std::ios::binary);auto get=[&](auto&v){f.read((char*)&v,sizeof(v));if(!f)throw std::runtime_error("driven CP truncated");};std::uint64_t magic,n,length;get(magic);get(n);get(length);if(magic!=0x315043544f534946ULL||n!=u.c.count||length!=64)throw std::runtime_error("driven CP schema/shape");std::string stored(length,' ');f.read(stored.data(),length);if(stored!=id)throw std::runtime_error("driven CP identity");for(int q:u.c.n){int v;get(v);if(v!=q)throw std::runtime_error("driven CP grid");}DrivenState s;get(s.steps);get(s.origin);for(auto*p:{&s.D,&s.P})for(double&v:*p)get(v);get(s.Dtotal);get(s.Ptotal);for(auto&sub:s.m){sub.resize(n);for(V&v:sub){get(v.x);get(v.y);get(v.z);if(!finite(v)||std::abs(norm(v)-1)>1e-12)throw std::runtime_error("driven CP state");}}for(auto&t:s.track){for(double&v:t.wrapped)get(v);for(double&v:t.unwrapped)get(v);get(t.has);get(t.continuous);if((t.has!=0&&t.has!=1)||(t.continuous!=0&&t.continuous!=1))throw std::runtime_error("driven CP observer");}if(f.peek()!=EOF||!std::isfinite(s.origin)||!std::isfinite(s.Dtotal)||!std::isfinite(s.Ptotal)||s.D[0]<0||s.D[1]<0)throw std::runtime_error("driven CP controls");for(double v:{s.D[0],s.D[1],s.P[0],s.P[1]})if(!std::isfinite(v))throw std::runtime_error("driven CP integral");return s;}
