int main(int argc,char**argv){std::filesystem::path out;unsigned long fields=0;try{
 if(argc!=10)throw std::runtime_error("CONFIG KERNEL STATE NEW_OUT TARGET_STEPS SAVE_EVERY ID seed|checkpoint SOT_CONFIG");UserConfig u=read_user(argv[1]);unsigned long target=std::stoul(argv[5]),save=std::stoul(argv[6]);std::string id=argv[7],kind=argv[8];auto drive=read_sot(argv[9],u,target);if(id.size()!=64||save<1)throw std::runtime_error("driven arguments");out=argv[4];if(std::filesystem::exists(out))throw std::runtime_error("output exists");std::filesystem::create_directories(out);DrivenState s;
 if(kind=="checkpoint")s=restore_driven(argv[3],u,id);else if(kind=="seed"){std::ifstream f(argv[3],std::ios::binary);for(auto&sub:s.m){sub.resize(u.c.count);f.read((char*)sub.data(),sub.size()*sizeof(V));}if(!f||f.peek()!=EOF)throw std::runtime_error("drive seed shape");for(auto&sub:s.m)for(V v:sub)if(!finite(v)||std::abs(norm(v)-1)>1e-12)throw std::runtime_error("drive seed unit");}else throw std::runtime_error("drive state kind");if(s.steps>target)throw std::runtime_error("drive resume beyond T");auto begin=Clock::now();UserModel model(u,argv[2]);auto guard=[&]{if(std::chrono::duration<double>(Clock::now()-begin).count()>u.wall||rss()>u.c.memory)throw std::runtime_error("resource_budget_exhausted");};
 auto eval=[&](const Spins&m){guard();if(fields>=u.fields)throw std::runtime_error("field_budget_exhausted");fields++;auto tmp=out/"counter.json.tmp";{std::ofstream f(tmp);f<<"{\"started_fields\":"<<fields<<"}\n";}std::filesystem::rename(tmp,out/"counter.json");auto e=model.eval(m);guard();return e;};auto current=eval(s.m);if(kind=="seed")s.origin=current.E;std::ofstream hist(out/"history.csv"),obs(out/"observations.csv");hist<<std::setprecision(17);obs<<std::setprecision(17);hist<<"step,time_ps,E_J,D_A_J,D_B_J,D_J,P_A_J,P_B_J,P_J,defect_J,residual_A_Apm,residual_B_Apm,raw_A,raw_B,fields\n";obs<<"step,time_ps,sub,Q,singular,wrapped_x_nm,wrapped_y_nm,x_nm,y_nm,radius_nm,shape,cores,closed_contours,valid_single,continuous\n";std::array<CurrentObservation,2>observation;std::array<double,2>raw{};unsigned long cp_step=s.steps;
 auto measure=[&](bool update){for(int i=0;i<2;i++)observation[i]=observe_current(s.m[i],u,drive,s.track[i],update);};measure(kind=="seed");
 auto emit=[&](bool frame){auto res=residual(s.m,current);hist<<s.steps<<','<<s.steps*u.dt*1e12<<','<<current.E<<','<<s.D[0]<<','<<s.D[1]<<','<<s.Dtotal<<','<<s.P[0]<<','<<s.P[1]<<','<<s.Ptotal<<','<<current.E-s.origin+s.Dtotal-s.Ptotal<<','<<res[0]<<','<<res[1]<<','<<raw[0]<<','<<raw[1]<<','<<fields<<'\n';hist.flush();for(int i=0;i<2;i++){auto&o=observation[i];obs<<s.steps<<','<<s.steps*u.dt*1e12<<','<<i<<','<<o.Q<<','<<o.singular<<','<<o.x<<','<<o.y<<','<<o.ux<<','<<o.uy<<','<<o.radius<<','<<o.shape<<','<<o.cores<<','<<o.closed<<','<<o.single<<','<<o.continuous<<'\n';}obs.flush();if(!hist||!obs)throw std::runtime_error("drive history output");if(frame){cp_step=s.steps;driven_cp(out/"checkpoint.bin",s,u,id);std::string tag="step_"+std::to_string(s.steps);snapshot(out/(tag+".bin"),s.m);blob(out/(tag+"_H_A.bin"),current.H[0]);blob(out/(tag+"_H_B.bin"),current.H[1]);Spins f=s.m;for(int i=0;i<2;i++)for(size_t j=0;j<u.c.count;j++)f[i][j]=sot_only(s.m[i][j],i,u,drive);snapshot(out/(tag+"_drive_rhs.bin"),f);std::ofstream e(out/(tag+"_energy.json"));e<<std::setprecision(17)<<"{\"parts_J\":[";for(int k=0;k<7;k++){if(k)e<<',';e<<current.Eparts[k];}e<<"]}\n";}
 auto tmp=out/"progress.json.tmp";{std::ofstream f(tmp);f<<std::setprecision(17)<<"{\"phase\":\"driven_dynamic\",\"step\":"<<s.steps<<",\"time_ps\":"<<s.steps*u.dt*1e12<<",\"E_J\":"<<current.E<<",\"D_A_J\":"<<s.D[0]<<",\"D_B_J\":"<<s.D[1]<<",\"P_A_J\":"<<s.P[0]<<",\"P_B_J\":"<<s.P[1]<<",\"fields\":"<<fields<<",\"checkpoint_step\":"<<cp_step<<",\"elapsed_s\":"<<std::chrono::duration<double>(Clock::now()-begin).count()<<"}\n";}std::filesystem::rename(tmp,out/"progress.json");guard();};emit(true);bool nonzero=norm(sot_cross(drive.d,drive.J))!=0&&(drive.xi[0]!=0||drive.xi[1]!=0);
 while(s.steps<target){auto e1=eval(s.m);auto k1=current_rhs(s.m,e1,u,drive);auto d1=power(s.m,e1,u);auto p1=current_work(s.m,e1,u,drive);auto m2=add(s.m,k1,u.dt/2);auto e2=eval(m2);auto k2=current_rhs(m2,e2,u,drive);auto d2=power(m2,e2,u);auto p2=current_work(m2,e2,u,drive);auto m3=add(s.m,k2,u.dt/2);auto e3=eval(m3);auto k3=current_rhs(m3,e3,u,drive);auto d3=power(m3,e3,u);auto p3=current_work(m3,e3,u,drive);auto m4=add(s.m,k3,u.dt);auto e4=eval(m4);auto k4=current_rhs(m4,e4,u,drive);auto d4=power(m4,e4,u);auto p4=current_work(m4,e4,u,drive);Spins next=s.m;raw={};for(int i=0;i<2;i++)for(size_t j=0;j<u.c.count;j++){next[i][j]+=(k1[i][j]+k2[i][j]*2+k3[i][j]*2+k4[i][j])*(u.dt/6);V q=next[i][j];double n=std::hypot(q.x,q.y,q.z);if(!finite(q)||!std::isfinite(n)||n==0)throw std::runtime_error("drive nonfinite raw");raw[i]=std::max(raw[i],std::abs(n-1));next[i][j]={q.x/n,q.y/n,q.z/n};}if(nonzero&&std::max(raw[0],raw[1])>drive.raw_limit)throw std::runtime_error("drive raw gate 1e-8");auto end=eval(next);double incD=0,incP=0;for(int i=0;i<2;i++){double dd=(d1[i]+2*d2[i]+2*d3[i]+d4[i])*u.dt/6,pp=(p1[i]+2*p2[i]+2*p3[i]+p4[i])*u.dt/6;s.D[i]+=dd;s.P[i]+=pp;incD+=dd;incP+=pp;}s.Dtotal+=incD;s.Ptotal+=incP;if(!std::isfinite(s.Dtotal)||!std::isfinite(s.Ptotal))throw std::runtime_error("drive integral nonfinite");s.m=std::move(next);current=std::move(end);s.steps++;measure(true);bool frame=s.steps==target||s.steps%save==0||std::binary_search(drive.events.begin(),drive.events.end(),s.steps);emit(frame);}
 snapshot(out/"final.bin",s.m);save_eval(out,"final",current);auto r=residual(s.m,current);std::ofstream result(out/"result.json");result<<std::setprecision(17)<<"{\"stop_reason\":\"physical_time\",\"step\":"<<s.steps<<",\"energy_J\":"<<current.E<<",\"origin_J\":"<<s.origin<<",\"D_A_J\":"<<s.D[0]<<",\"D_B_J\":"<<s.D[1]<<",\"D_J\":"<<s.Dtotal<<",\"P_A_J\":"<<s.P[0]<<",\"P_B_J\":"<<s.P[1]<<",\"P_J\":"<<s.Ptotal<<",\"defect_J\":"<<current.E-s.origin+s.Dtotal-s.Ptotal<<",\"residual_A_Apm\":"<<r[0]<<",\"residual_B_Apm\":"<<r[1]<<",\"fields\":"<<fields<<",\"wall_s\":"<<std::chrono::duration<double>(Clock::now()-begin).count()<<",\"RSS_bytes\":"<<rss()<<"}\n";result.flush();if(!result)throw std::runtime_error("drive result output");return 0;
 }catch(const std::exception&e){if(!out.empty()&&std::filesystem::exists(out)){std::ofstream f(out/"failure.json");f<<"{\"fields_started\":"<<fields<<"}\n";std::ofstream(out/"failure.txt")<<e.what();}std::cerr<<e.what()<<'\n';return 2;}}

